template<typename T>
void sink(T&& arg) {
    // Universal Reference: T&& on deduced type
    // If arg is lvalue, T deduces to T_LVAL&
    // If arg is rvalue, T deduces to T_RVAL

    // Pass it perfectly:
    other_func(std::forward<T>(arg)); 
}

// Example usage:
Resource r;
sink(r);      // T deduces to Resource&, forwarded as lvalue
sink(Resource{}); // T deduces to Resource, forwarded as rvalue
// The compiler's implementation hinges on its ability to deduce the 'T' type correctly.
